<section class="content"><div class="page-intro"><p>Search donors by blood group and location. Only donors who are currently available are shown.</p></div><form class="filter-bar" method="get"><input type="hidden" name="page" value="find-donor"><select name="blood_group"><option value="">All blood groups</option><?php foreach (['A+','A-','B+','B-','AB+','AB-','O+','O-'] as $group): ?><option <?= ($_GET['blood_group'] ?? '') === $group ? 'selected' : '' ?>><?= $group ?></option><?php endforeach; ?></select><input name="location" value="<?= h($_GET['location'] ?? '') ?>" placeholder="Search by location"><button class="button secondary">Search</button></form><div class="donor-grid"><?php $found = array_filter($all_users, fn($u) => $u['role'] === 'donor' && !empty($u['available']) && (!($_GET['blood_group'] ?? '') || $u['blood_group'] === $_GET['blood_group']) && (!($_GET['location'] ?? '') || stripos($u['location'], $_GET['location']) !== false)); foreach ($found as $donor): ?><div class="donor-card"><div class="donor-top"><div class="avatar large"><?= h(strtoupper(substr($donor['name'], 0, 1))) ?></div><span class="online">Available</span></div><h3><?= h($donor['name']) ?></h3><p><?= h($donor['location']) ?></p><div class="donor-meta"><strong><?= h($donor['blood_group']) ?></strong><span>Blood group</span></div><a class="button outline wide" href="mailto:<?= h($donor['email']) ?>">Contact donor <span>→</span></a></div><?php endforeach; ?></div><?php if (!$found): ?><div class="empty">No available donors match those filters.</div><?php endif; ?></section>